#include "stdafx.h"#include "Common.h"#include "Queue.h"#include "..\Lang.h"//// Обработка кнопок//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ, public SBtnDataEx  {  char szGoto[64];  bool m_bPress;  char szPointName[128];  } Queue_Watch;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int PressWatch(DefinePress)  {  Queue_Watch* p = (Queue_Watch*)s;  if ( nCode == 0 && !p->m_bPress )    p->m_bPressed = true;  else  if ( nCode == 1 )    { }  else  if ( nCode == 2 )    p->m_bPressed = false;  //  bool bPtInRect = ::PtInRect( &p->mRect, point ) == TRUE;  bool bPressed = p->m_bPressed;  if ( bPressed )    bPressed = bPtInRect;  //  HDC hDC = ::GetDC( q.hWnd );  if ( hDC != NULL )    {    {    MYWT;    ::PaintButton( hDC, p->mRect, p, bPressed, false );    }    ::ReleaseDC( q.hWnd, hDC );    }  //  if ( nCode == 2 && bPtInRect && !p->m_bPress )    {    char szText[256];	sprintf_s( szText, sizeof( szText ), "Объект %s' осмотрен", p->szPointName );    //    SSendToModel send;    send.eData = id_Msg;	send.eType = (EValueType)CEventLogType::etRsuAction;    lstrcpyn( send.szName, szText, sizeof(send.szName)+sizeof(send.szValue) );    q.m_pPipe->SendData( send, true );    //    p->m_bPress = true;    p->txtNorma = 0x808080;	lstrcpy( p->szName, "Осмотрен" );    ::InvalidateRect( q.hWnd, NULL, FALSE );    }  //  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintWatch(DefinePaint)  {  QueueP(Queue_Watch);  //  bool bPressed = ::PressedButton( p, p->mRect, q );  ::PaintButton( hDC, p->mRect, p, bPressed, false );  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddWatch(DefineTegs)  {  //  AddQueueEx(Queue_Watch);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_BUTTON;  // Определение функции вывода  p->paint = &PaintWatch;  p->press = &PressWatch;  lstrcpy(p->szPointName,"");  //  DefaultButton( p, teg[0].value );  //  STegObj obj[] =    {	{ 'S', "pointName", p->szPointName, 127 },    TEG_BUTTON // Кнопочная информация    EXT_QUEUE  // Дополнительная информация    //    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  if (lstrcmp(p->szPointName,"")==0)  {	  int nActive;	  nActive  = def.GetActiveObjSocket();	  if (nActive!=-1)	  {		  const char* name = def.GetModelName(nActive);		  sprintf_s( p->szPointName, sizeof(p->szPointName), "%s", name );	  }  }  PostfixButton( p );  //  ::InflateRect( &p->mRect, -1, -1 );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~